def close(x, ref, rtol: float = 1e-12, atol: float = 1e-14) -> bool:
    a = np.asarray(x).astype(float)
    r = np.asarray(ref).astype(float)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if not (abs(u - v) <= atol + rtol * abs(v) or (u != u and v != v) or u == v):
            print('mismatch', u, v)
            ok = False
    return ok

