@test
def test_means():
    assert close(st.gmean(x), gm)
    assert close(st.gmean(X2, axis=1), gm_ax1)
    assert close(st.gmean(x, weights=y), gm_w)
    assert close(st.hmean(x), hm)
    assert close(st.hmean(x, weights=y), hm_w)
    assert close([st.pmean(x, 2.5), st.pmean(x, -1.5), st.pmean(x, 1e-7), st.pmean(x, 3., weights=y)], pm)
    m = st.mode(np.array([1., 2., 2., 3., 3., 3., 4.]))
    assert close([m.mode, float(m.count)], mo)
    m2 = st.mode(np.array([[1., 2., 2.], [3., 3., 1.], [1., 2., 3.]]), axis=0)
    assert close(m2.mode, mo2[0])
    assert close(m2.count.astype(float), mo2[1])
test_means()

@test
def test_trimmed():
    assert close([st.tmean(x), st.tmean(x, (2.0, 5.0)), st.tmean(x, (2.2, 5.0), (False, True))], tmn)
    assert close([st.tvar(x), st.tvar(x, (2.0, 5.0)), st.tstd(x, (2.0, 5.0)), st.tsem(x, (2.0, 5.0)), st.tsem(x)], tvr)
    assert close([st.tmin(x, 2.5), st.tmax(x, 5.0), st.tmin(x), st.tmax(x, 5.0, inclusive=False)], tmm)
    assert close(st.tmean(X2, (2.0, 6.0)), tmean2)
    assert close(st.tvar(X2, (2.0, 6.5), axis=1), tvar_ax)
    assert close(np.sort(st.trimboth(x, 0.2)), trb)
    assert close(np.sort(st.trim1(x, 0.25)), tr1)
    assert close(np.sort(st.trim1(x, 0.25, tail='left')), tr1l)
    assert close([st.trim_mean(x, 0.1), st.trim_mean(x, 0.25)], trm)
    assert close(st.trim_mean(X2, 0.2, axis=1), trm_ax)
test_trimmed()

@test
def test_dispersion():
    assert close([st.variation(x), st.variation(x, ddof=1)], var)
    assert close(st.variation(X2, axis=0), var_ax)
    assert close([st.iqr(x), st.iqr(x, rng=(10, 80)), st.iqr(x, scale='normal'),
                  st.iqr(x, interpolation='lower'), st.iqr(x, interpolation='midpoint'),
                  st.iqr(x, interpolation='nearest'), st.iqr(x, interpolation='higher')], iq)
    assert close(st.iqr(X2, axis=1), iq_ax)
    assert close([st.median_abs_deviation(x), st.median_abs_deviation(x, scale='normal')], mad)
    assert close(st.median_abs_deviation(X2, axis=1), mad_ax)
    assert close([st.percentileofscore(x, 3.4), st.percentileofscore(x, 3.4, kind='strict'),
                  st.percentileofscore(x, 3.4, kind='weak'), st.percentileofscore(x, 3.4, kind='mean'),
                  st.percentileofscore(x, 3.5)], pos)
    assert close([st.scoreatpercentile(x, 30), st.scoreatpercentile(x, 50, interpolation_method='lower'),
                  st.scoreatpercentile(x, 37, interpolation_method='higher'),
                  st.scoreatpercentile(x, 40, limit=(2.0, 5.0))], sap)
    assert close(st.scoreatpercentile(x, [10, 90]), sap_v)
test_dispersion()

@test
def test_entropy_freq():
    pk = np.array([0.1, 0.2, 0.3, 0.4])
    qk = np.array([0.25, 0.25, 0.3, 0.2])
    assert close([st.entropy(pk), st.entropy(pk, base=2), st.entropy(pk, qk), st.entropy([3., 1., 0., 2.])], ent)
    assert close(st.entropy(X2, axis=1), ent_ax)
    b = np.array(big)
    assert close([st.differential_entropy(x), st.differential_entropy(b),
                  st.differential_entropy(b, method='vasicek'), st.differential_entropy(b, method='van es'),
                  st.differential_entropy(b, method='correa'), st.differential_entropy(b, window_length=3, base=2)], dent)
    c = st.cumfreq(x, numbins=4)
    assert close(list(c.cumcount) + [c.lowerlimit, c.binsize, float(c.extrapoints)], cf)
    r = st.relfreq(x, numbins=5, defaultreallimits=(2.0, 5.0))
    assert close(list(r.frequency) + [r.lowerlimit, r.binsize, float(r.extrapoints)], rf)
    r2 = st.relfreq(x, numbins=3, weights=y)
    assert close(list(r2.frequency) + [r2.lowerlimit, r2.binsize, float(r2.extrapoints)], rfw)
    fr = st.find_repeats([2., 1., 2., 3., 2., 2., 5., 3.])
    assert close(fr.values, frv)
    assert close(fr.counts.astype(float), frc)
    assert close([st.wasserstein_distance(x, y), st.wasserstein_distance(x, y[:7], y, y[:7]),
                  st.energy_distance(x, y), st.energy_distance(x, y[:7], y, y[:7])], wd)
test_entropy_freq()

@test
def test_circ_fdr():
    ang = np.array([0.1, 6.2, 0.4, 5.9, 1.0, 0.3])
    dg = np.array([355., 5., 2., 359.])
    assert close([st.circmean(ang), st.circvar(ang), st.circstd(ang), st.circstd(ang, normalize=True),
                  st.circmean(dg, high=360), st.circstd(dg, high=360)], circ)
    assert close(st.circmean(X2, axis=1), circ_ax)
    ps = np.array([0.01, 0.04, 0.03, 0.2, 0.5, 0.008, 0.9])
    assert close(st.false_discovery_control(ps), fdr)
    assert close(st.false_discovery_control(ps, method='by'), fdr_by)
test_circ_fdr()

@test
def test_boxcox_yj():
    assert close([st.boxcox_llf(0.5, x), st.boxcox_llf(0.0, x), st.boxcox_llf(-1.3, x)], bcllf)
    yb, lm = st.boxcox(x)
    assert close(lm, bc_l, rtol=1e-9)
    assert close(yb, bc_y, rtol=1e-9)
    assert close(st.boxcox(x, 0.3), bc_fix)
    assert close([st.boxcox_normmax(x), st.boxcox_normmax(x, method='mle')], bcn, rtol=1e-9)
    r = st.boxcox(x, alpha=0.05)
    assert close([r[2][0], r[2][1]], bc_ci, rtol=1e-9)
    assert close([st.yeojohnson_llf(0.5, Z), st.yeojohnson_llf(0.0, x), st.yeojohnson_llf(1.7, -x)], yjllf)
    yj, lj = st.yeojohnson(Z)
    assert close(lj, yj_l, rtol=1e-9)
    assert close(yj, yj_y, rtol=1e-9)
    assert close(st.yeojohnson(Z, 0.7), yj_fix)
    assert close([st.yeojohnson_normmax(x), st.yeojohnson_normmax(-x)], yjn, rtol=1e-9)
test_boxcox_yj()
